package com.hermes.agent.domain.model

import com.google.gson.JsonArray
import com.google.gson.JsonObject
import com.google.gson.JsonParser

/**
 * A file shown in the chat. [uri] is either a path relative to the app's files directory (saved files)
 * or an https URL (images linked in a reply, previewed without downloading).
 */
data class Attachment(
    val name: String,
    val mime: String,
    val uri: String,
    val size: Long = 0,
    /** Where it came from, e.g. "generated by google/gemini-3-pro-image" or a license line. */
    val caption: String = ""
) {
    val isRemote get() = uri.startsWith("http://") || uri.startsWith("https://")
    val kind: Kind get() = when {
        mime.startsWith("image/") -> Kind.IMAGE
        mime.startsWith("video/") -> Kind.VIDEO
        mime.startsWith("audio/") -> Kind.AUDIO
        else -> Kind.FILE
    }

    enum class Kind { IMAGE, VIDEO, AUDIO, FILE }

    companion object {
        /** Stored as a JSON array built by hand: no reflection, so R8 can't break it. */
        fun encode(list: List<Attachment>): String? = if (list.isEmpty()) null else JsonArray().apply {
            list.forEach { a ->
                add(JsonObject().apply {
                    addProperty("name", a.name); addProperty("mime", a.mime); addProperty("uri", a.uri)
                    addProperty("size", a.size); addProperty("caption", a.caption)
                })
            }
        }.toString()

        fun decode(json: String?): List<Attachment> = if (json.isNullOrBlank()) emptyList() else runCatching {
            JsonParser.parseString(json).asJsonArray.map { el ->
                val o = el.asJsonObject
                Attachment(
                    name = o.get("name").asString, mime = o.get("mime").asString, uri = o.get("uri").asString,
                    size = o.get("size")?.asLong ?: 0, caption = o.get("caption")?.asString.orEmpty()
                )
            }
        }.getOrDefault(emptyList())
    }
}
